module robot_reach(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] char,\n    input wire char_valid,\n    input wire [6:0] len,\n    input wire signed [31:0] a,\n    input wire signed [31:0] b,\n    output reg result,\n    output reg done\n);\n\n    // State definitions\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] RECEIVE = 2'd1;\n    localparam [1:0] CHECK = 2'd2;\n    localparam [1:0] FINISHED = 2'd3;\n\n    // Internal registers\n    reg [1:0] state;\n    reg [6:0] count;\n    reg signed [31:0] current_x, current_y;\n    reg signed [31:0] dx, dy;\n    reg [6:0] index;\n    reg signed [31:0] x_mem [0:100];\n    reg signed [31:0] y_mem [0:100];\n\n    // Helper signals for condition checking\n    wire signed [31:0] ax = a - x_mem[index];\n    wire signed [31:0] by = b - y_mem[index];\n    wire signed [63:0] prod1 = ax * dy;\n    wire signed [63:0] prod2 = by * dx;\n    wire sign_ok_dx = (dx > 0 && ax >= 0) || (dx < 0 && ax <= 0) || (dx == 0);\n    wire sign_ok_dy = (dy > 0 && by >= 0) || (dy < 0 && by <= 0) || (dy == 0);\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 1'b0;\n            count <= 7'd0;\n            index <= 7'd0;\n            current_x <= 32'd0;\n            current_y <= 32'd0;\n            dx <= 32'd0;\n            dy <= 32'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    if (start) begin\n                        state <= RECEIVE;\n                        count <= 7'd0;\n                        current_x <= 32'd0;\n                        current_y <= 32'd0;\n                        x_mem[0] <= 32'd0;\n                        y_mem[0] <= 32'd0;\n                        done <= 1'b0;\n                        result <= 1'b0;\n                    end\n                end\n\n                RECEIVE: begin\n                    if (char_valid) begin\n                        // Update current position\n                        case (char)\n                            "U", "u": current_y <= current_y + 32'd1;\n                            "D", "d": current_y <= current_y - 32'd1;\n                            "L", "l": current_x <= current_x - 32'd1;\n                            "R", "r": current_x <= current_x + 32'd1;\n                            default: ; // Ignore invalid\n                        endcase\n                        \n                        // Store new position\n                        x_mem[count + 1] <= current_x;\n                        y_mem[count + 1] <= current_y;\n                        \n                        count <= count + 7'd1;\n                        \n                        if (count + 1 == len) begin\n                            dx <= current_x;\n                            dy <= current_y;\n                            state <= CHECK;\n                            index <= 7'd0;\n                        end\n                    end\n                end\n\n                CHECK: begin\n                    if (index <= len) begin\n                        if (dx == 0 && dy == 0) begin\n                            if (a == x_mem[index] && b == y_mem[index]) begin\n                                result <= 1'b1;\n                                state <= FINISHED;\n                            end else if (index == len) begin\n                                result <= 1'b0;\n                                state <= FINISHED;\n                            end else begin\n                                index <= index + 7'd1;\n                            end\n                        end else if (dx == 0) begin\n                            if (a == x_mem[index]) begin\n                                if (b == y_mem[index]) begin\n                                    result <= 1'b1;\n                                    state <= FINISHED;\n                                end else if (dy != 0 && (b - y_mem[index]) % dy == 0) begin\n                                    integer k = (b - y_mem[index]) / dy;\n                                    if (k >= 0) begin\n                                        result <= 1'b1;\n                                        state <= FINISHED;\n                                    end else if (index == len) begin\n                                        result <= 1'b0;\n                                        state <= FINISHED;\n                                    end else begin\n                                        index <= index + 7'd1;\n                                    end\n                                end else if (index == len) begin\n                                    result <= 1'b0;\n                                    state <= FINISHED;\n                                end else begin\n                                    index <= index + 7'd1;\n                                end\n                            end else if (index == len) begin\n                                result <= 1'b0;\n                                state <= FINISHED;\n                            end else begin\n                                index <= index + 7'd1;\n                            end\n                        end else if (dy == 0) begin\n                            if (b == y_mem[index]) begin\n                                if (a == x_mem[index]) begin\n                                    result <= 1'b1;\n                                    state <= FINISHED;\n                                end else if (dx != 0 && (a - x_mem[index]) % dx == 0) begin\n                                    integer k = (a - x_mem[index]) / dx;\n                                    if (k >= 0) begin\n                                        result <= 1'b1;\n                                        state <= FINISHED;\n                                    end else if (index == len) begin\n                                        result <= 1'b0;\n                                        state <= FINISHED;\n                                    end else begin\n                                        index <= index + 7'd1;\n                                    end\n                                end else if (index == len) begin\n                                    result <= 1'b0;\n                                    state <= FINISHED;\n                                end else begin\n                                    index <= index + 7'd1;\n                                end\n                            end else if (index == len) begin\n                                result <= 1'b0;\n                                state <= FINISHED;\n                            end else begin\n                                index <= index + 7'd1;\n                            end\n                        end else begin\n                            // Both dx and dy non-zero\n                            if (prod1 == prod2 && sign_ok_dx && sign_ok_dy) begin\n                                result <= 1'b1;\n                                state <= FINISHED;\n                            end else if (index == len) begin\n                                result <= 1'b0;\n                                state <= FINISHED;\n                            end else begin\n                                index <= index + 7'd1;\n                            end\n                        end\n                    end else begin\n                        result <= 1'b0;\n                        state <= FINISHED;\n                    end\n                end\n\n                FINISHED: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule